"""cam_studio.server — HTTP сервер нового приложения CamStudio."""

import http.server
import json
import os
import sys
import urllib.parse
from .cam.generator import CamStudioGenerator
from .cam.chipload import calculate_feeds_speeds

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
UI_DIR = os.path.join(BASE_DIR, "ui")


class CamStudioHandler(http.server.BaseHTTPRequestHandler):
    last_generated_nc = ""

    def log_message(self, *args):
        pass

    def _send(self, code, content_type, body):
        if isinstance(body, str):
            body = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-cache")
        self.end_headers()
        self.wfile.write(body)

    def _json(self, obj, code=200):
        self._send(code, "application/json; charset=utf-8", json.dumps(obj, ensure_ascii=False))

    def _body(self):
        length = int(self.headers.get("Content-Length") or 0)
        if not length:
            return {}
        raw = self.rfile.read(length).decode("utf-8")
        return json.loads(raw)

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path

        if path in ("/", "/index.html"):
            p = os.path.join(UI_DIR, "index.html")
            with open(p, "rb") as f:
                return self._send(200, "text/html; charset=utf-8", f.read())

        if path.startswith("/ui/"):
            rel = path[4:]
            full = os.path.join(UI_DIR, rel)
            if os.path.isfile(full):
                ext = os.path.splitext(full)[1]
                ct = {
                    ".html": "text/html",
                    ".js": "application/javascript",
                    ".css": "text/css",
                    ".svg": "image/svg+xml"
                }.get(ext, "application/octet-stream")
                with open(full, "rb") as f:
                    return self._send(200, ct, f.read())

        if path == "/api/download":
            nc = CamStudioHandler.last_generated_nc or "( No G-code generated yet )\n"
            self.send_response(200)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Disposition", 'attachment; filename="camstudio_job.nc"')
            self.send_header("Content-Length", str(len(nc.encode("utf-8"))))
            self.end_headers()
            self.wfile.write(nc.encode("utf-8"))
            return

        self._send(404, "text/plain", "Not Found")

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path

        if path == "/api/chipload":
            try:
                b = self._body()
                res = calculate_feeds_speeds(
                    tool_dia_mm=float(b.get('dia', 6.35)),
                    flutes=int(b.get('flutes', 2)),
                    material=b.get('material', 'walnut'),
                    target_rpm=int(b.get('rpm', 18000)),
                    cut_depth_mm=float(b.get('stepdown', 3.5))
                )
                return self._json(res)
            except Exception as e:
                return self._json({"error": str(e)}, 400)

        if path == "/api/generate":
            try:
                b = self._body()
                gen = CamStudioGenerator(b)
                result = gen.build()
                CamStudioHandler.last_generated_nc = result['gcode']
                return self._json(result)
            except Exception as e:
                return self._json({"error": str(e)}, 500)

        self._send(404, "text/plain", "Not Found")


def run_server(port=8080):
    server = http.server.HTTPServer(("127.0.0.1", port), CamStudioHandler)
    print(f"CamStudio Next-Gen Wood CAM: http://127.0.0.1:{port}/ (Ctrl+C to stop)")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    return 0


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8080
    run_server(port)
